#!/usr/bin/env bash
# Checks that every commit in the given range follows Conventional Commits
# 1.0.0 and carries no AI co-author trailer.
#
# Usage: scripts/check-commits.sh <revision-range>   (e.g. origin/main..HEAD)
set -euo pipefail

range="${1:?usage: $0 <revision-range>}"
pattern='^(build|chore|ci|docs|feat|fix|perf|refactor|revert|style|test)(\([a-z0-9][a-z0-9-]*\))?!?: [^ ].*$'
# Co-author trailers of coding agents and "generated by" lines: say in the
# pull request description that an agent helped instead (CONTRIBUTING.md).
ai_trailer='^(co-authored-by:.*(claude|anthropic|copilot|openai|chatgpt|codex|gemini|cursor|devin|aider|noreply@(anthropic|openai)\.com)|.*generated (with|by) .*(claude|copilot|chatgpt|codex|gemini|cursor|aider|devin))'
# Resolve the range first: an unknown revision must fail the check, not
# yield an empty list of commits.
git rev-list --no-merges "$range" > /dev/null || { echo "invalid revision range: $range" >&2; exit 2; }
status=0

while read -r sha; do
  subject="$(git log -1 --format=%s "$sha")"
  if ! grep -Eq "$pattern" <<<"$subject"; then
    echo "$sha: subject does not follow Conventional Commits: $subject" >&2
    status=1
  fi
  if git log -1 --format=%B "$sha" | grep -Eiq "$ai_trailer"; then
    echo "$sha: AI co-author trailers are not allowed" >&2
    status=1
  fi
done < <(git rev-list --no-merges "$range")

exit "$status"
